// OFL 1.1 fonts (Figtree, Bricolage Grotesque), Latin-1/Latin Extended-A subsets (other scripts fall back to the system font) inlined so the strict CSP needs only font-src data:.
export const BRAND_FONT_CSS='@font-face{font-family:"Figtree";src:url(data:font/woff2;base64,) format("woff2");font-weight:400 700;font-display:swap}@font-face{font-family:"Bricolage Grotesque";src:url(data:font/woff2;base64,) format("woff2");font-weight:800;font-display:swap}';
